program.source:
Funcion total <- SumaHasta(n Como Entero)
  Definir total Como Entero;
  total <- n + SumaHasta(n - 1);
FinFuncion

Algoritmo Principal
  Definir n Como Entero;
  Leer n;
  Escribir SumaHasta(n);
FinAlgoritmo

